import json

def transform_v3(grid):
    """Fill gaps in single-color frames with 2s"""
    if not grid:
        return grid

    grid = [list(row) for row in grid]
    rows, cols = len(grid), len(grid[0])

    # Find colors
    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            color_counts[grid[r][c]] = color_counts.get(grid[r][c], 0) + 1
    background = max(color_counts.keys(), key=lambda x: color_counts[x])

    non_bg = [(c, cnt) for c, cnt in color_counts.items() if c != background]
    non_bg.sort(key=lambda x: x[1], reverse=True)

    if not non_bg:
        return grid

    frame_color = non_bg[0][0]

    result = [row[:] for row in grid]

    # Find frame range
    frame_rows = set()
    frame_cols = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == frame_color:
                frame_rows.add(r)
                frame_cols.add(c)

    if not frame_rows:
        return grid

    min_r, max_r = min(frame_rows), max(frame_rows)
    min_c, max_c = min(frame_cols), max(frame_cols)

    # For each position that could be a gap
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if grid[r][c] != frame_color:
                # Check for row gaps
                # Has frame somewhere in the row, and this position is between frame cells
                any_frame_in_row = any(grid[r][cc] == frame_color for cc in range(0, cols))

                if any_frame_in_row:
                    # Check if there's frame to the left (before this column)
                    has_frame_before = any(grid[r][cc] == frame_color for cc in range(0, c))
                    # Check if there's frame to the right (after this column)
                    has_frame_after = any(grid[r][cc] == frame_color for cc in range(c+1, cols))

                    if has_frame_before and has_frame_after:
                        # This is a gap between frames in the same row
                        result[r][c] = 2
                        continue

        # Check boundary gaps (at min_c or max_c positions)
        for c in [min_c, max_c]:
            for r in range(min_r, max_r + 1):
                if grid[r][c] != frame_color:
                    # Check if this row has any frame elsewhere
                    any_frame_in_row = any(grid[r][cc] == frame_color for cc in range(min_c, max_c+1))
                    if any_frame_in_row:
                        # This position should have frame if there's row symmetry
                        # Check if any OTHER row at min_c has frame
                        col_has_frame = any(grid[rr][c] == frame_color for rr in range(min_r, max_r+1))
                        if col_has_frame:
                            result[r][c] = 2

    return result

